using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using StbMonitoring.Application.Interfaces;using StbMonitoring.Domain.Constants;
namespace StbMonitoring.Api.Controllers;
[ApiController,Route("api/alerts"),Authorize]public sealed class AlertsController(IOperationsService service,IIdentityStore identity):ControllerBase
{[HttpGet,Authorize(Policy=PermissionNames.AlertsRead)]public async Task<IActionResult>All(CancellationToken ct)=>Ok(await service.AlertsAsync(ct));[HttpGet("{id:guid}"),Authorize(Policy=PermissionNames.AlertsRead)]public async Task<IActionResult>One(Guid id,CancellationToken ct){var x=await service.AlertAsync(id,ct);return x is null?NotFound():Ok(x);}[HttpPost("{id:guid}/acknowledge"),Authorize(Policy=PermissionNames.AlertsAcknowledge)]public async Task<IActionResult>Acknowledge(Guid id,CancellationToken ct){await service.AcknowledgeAsync(id,Actor(),ct);await Audit("ALERT_ACKNOWLEDGED",id,ct);return NoContent();}[HttpPost("{id:guid}/resolve"),Authorize(Policy=PermissionNames.AlertsAcknowledge)]public async Task<IActionResult>Resolve(Guid id,CancellationToken ct){await service.ResolveAlertAsync(id,ct);await Audit("ALERT_RESOLVED",id,ct);return NoContent();}[HttpPost("{id:guid}/close"),Authorize(Policy=PermissionNames.AlertsAcknowledge)]public async Task<IActionResult>Close(Guid id,CancellationToken ct){await service.CloseAlertAsync(id,Actor(),ct);await Audit("ALERT_CLOSED",id,ct);return NoContent();}private Guid Actor()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);private async Task Audit(string action,Guid id,CancellationToken ct){identity.AddAudit(new(Actor(),action,"Alert",id,null,HttpContext.Connection.RemoteIpAddress?.ToString()));await identity.SaveChangesAsync(ct);}}
